const digestBytes = Buffer.from(DIGESTS_BASE64, 'base64');
if (digestBytes.length !== 3000 * 32) throw new Error('COMMON_PASSWORD_SET_CORRUPT');
const commonDigests = new Set<string>();
for (let offset = 0; offset < digestBytes.length; offset += 32)
  commonDigests.add(digestBytes.subarray(offset, offset + 32).toString('hex'));
if (commonDigests.size !== 3000) throw new Error('COMMON_PASSWORD_SET_CORRUPT');
export const COMMON_PASSWORD_COUNT = commonDigests.size;
export function isCommonPassword(password: string): boolean {
  return commonDigests.has(createHash('sha256').update(password, 'utf8').digest('hex'));
}
